import{_ as p,r as a,o,c as l,e as s,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"|link - October CMS - 4.x","titleTemplate":false,"description":"Twig Filter","frontmatter":{"subtitle":"Twig Filter"},"headers":[{"level":2,"title":"Supplying URL Parameters","slug":"supplying-url-parameters","link":"#supplying-url-parameters","children":[]},{"level":2,"title":"link()","slug":"link","link":"#link","children":[{"level":3,"title":"Nested Items","slug":"nested-items","link":"#nested-items","children":[{"level":4,"title":"Replacing Parent with Children","slug":"replacing-parent-with-children","link":"#replacing-parent-with-children","children":[]}]},{"level":3,"title":"URL Parameters","slug":"url-parameters","link":"#url-parameters","children":[]}]},{"level":2,"title":"PHP Interface","slug":"php-interface","link":"#php-interface","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/markup/filter/link.md","filePath":"4.x/markup/filter/link.md"}'),u={name:"4.x/markup/filter/link.md"};function r(k,n,g,d,m,h){const t=a("pre-heading"),e=a("post-heading");return o(),l("div",null,[s(t),n[0]||(n[0]=c("h1",null,"|link",-1)),s(e),n[1]||(n[1]=i(`<p>The <code>|link</code> filter returns a link generated using the <code>october://</code> output schema of a <a href="./../../element/form/widget-pagefinder.html">page finder form widget</a>. The result is a public URL to the page specified by the form widget.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>october://cms-page@link/about<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>link <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><div class="custom-block tip"><p>If you are looking to parse HTML for multiple links and resolve them as HTTP links in the output, see the <a href="./../tag/content.html"><code>|content</code> Twig filter</a>.</p></div><div class="custom-block warning"><p>The <code>|link</code> filter only returns the URL string. If you need to access nested child items from dynamic page types (like &quot;All Blog Posts&quot; or &quot;All Categories&quot;), use the <code>link()</code> function with the <code>nesting</code> option instead.</p></div><h2 id="supplying-url-parameters"><a href="#supplying-url-parameters" class="header-anchor">#</a> Supplying URL Parameters</h2><p>You may pass URL parameters to the <code>|link</code> filter to supply values for the target page&#39;s URL pattern. This is useful when the stored link reference doesn&#39;t contain the parameter values needed to build the URL.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> product<span class="token punctuation">.</span>custom_page<span class="token operator">|</span>link<span class="token punctuation">(</span><span class="token punctuation">{</span> slug<span class="token punctuation">:</span> product<span class="token punctuation">.</span>slug<span class="token punctuation">,</span> id<span class="token punctuation">:</span> product<span class="token punctuation">.</span>id <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>For example, if the selected CMS page has the URL pattern <code>/shop/product/:slug/:id</code>, the above will produce a URL like <code>/shop/product/my-product/42</code>.</p><h2 id="link"><a href="#link" class="header-anchor">#</a> link()</h2><p>The <code>link()</code> function is used to extract more detailed information about a link, including dynamically generated child items.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> resolved <span class="token operator">=</span> link<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>october://cms-page@link/about<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> resolved<span class="token punctuation">.</span>url <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>The following properties can be expected in the resulting object.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Data</th></tr></thead><tbody><tr><td><strong>url</strong></td><td>the public URL to the page.</td></tr><tr><td><strong>mtime</strong></td><td>the modification time of the page link.</td></tr><tr><td><strong>title</strong></td><td>a human readable title for the link, optional.</td></tr><tr><td><strong>items</strong></td><td>an array containing generated child items, optional.</td></tr><tr><td><strong>isActive</strong></td><td>set to true if the link is currently active.</td></tr></tbody></table></div><h3 id="nested-items"><a href="#nested-items" class="header-anchor">#</a> Nested Items</h3><p>You may request nested child items by passing the <code>nesting</code> option to <code>true</code> (second argument), which populates the <code>items</code> property on the result. This is essential when working with dynamic page types that generate multiple items, such as &quot;All Blog Posts&quot; or &quot;All Categories&quot;.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> resolved <span class="token operator">=</span> link<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>october://...<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token punctuation">{</span> nesting<span class="token punctuation">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> subitem <span class="token operator">in</span> resolved<span class="token punctuation">.</span>items <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> subitem<span class="token punctuation">.</span>url <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> subitem<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Each child item in the <code>items</code> array contains the same properties: <code>url</code>, <code>title</code>, <code>mtime</code>, <code>isActive</code>, and potentially nested <code>items</code> of its own for hierarchical structures.</p><h4 id="replacing-parent-with-children"><a href="#replacing-parent-with-children" class="header-anchor">#</a> Replacing Parent with Children</h4><p>When building menus with dynamic page types, you may want to replace a menu item with its generated children. This can be achieved by checking a stored flag and iterating the resolved items.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> item <span class="token operator">in</span> menu<span class="token punctuation">.</span>items <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> resolved <span class="token operator">=</span> link<span class="token punctuation">(</span>item<span class="token punctuation">.</span>reference<span class="token punctuation">,</span> <span class="token punctuation">{</span> nesting<span class="token punctuation">:</span> item<span class="token punctuation">.</span>nesting <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> item<span class="token punctuation">.</span>replace <span class="token operator">and</span> resolved<span class="token punctuation">.</span>items <span class="token delimiter punctuation">%}</span></span>
        <span class="token twig language-twig"><span class="token comment">{# Replace parent with its generated children #}</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> child <span class="token operator">in</span> resolved<span class="token punctuation">.</span>items <span class="token delimiter punctuation">%}</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> child<span class="token punctuation">.</span>url <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> child<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">else</span> <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> resolved<span class="token punctuation">.</span>url <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> item<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> resolved<span class="token punctuation">.</span>items <span class="token delimiter punctuation">%}</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
                <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> child <span class="token operator">in</span> resolved<span class="token punctuation">.</span>items <span class="token delimiter punctuation">%}</span></span>
                    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> child<span class="token punctuation">.</span>url <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> child<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
                <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>You may request other site URLs by passing the <code>sites</code> option to <code>true</code>, which populates the <code>sites</code> property on the result.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> resolved <span class="token operator">=</span> link<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>october://...<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token punctuation">{</span> sites<span class="token punctuation">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> site <span class="token operator">in</span> resolved<span class="token punctuation">.</span>sites <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> site<span class="token punctuation">.</span>url <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="url-parameters"><a href="#url-parameters" class="header-anchor">#</a> URL Parameters</h3><p>You may supply URL parameters using the <code>params</code> option. This is useful when combining parameter resolution with other options like <code>nesting</code> or <code>sites</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> resolved <span class="token operator">=</span> link<span class="token punctuation">(</span>product<span class="token punctuation">.</span>custom_page<span class="token punctuation">,</span> <span class="token punctuation">{</span>
    params<span class="token punctuation">:</span> <span class="token punctuation">{</span> slug<span class="token punctuation">:</span> product<span class="token punctuation">.</span>slug<span class="token punctuation">,</span> id<span class="token punctuation">:</span> product<span class="token punctuation">.</span>id <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><div class="custom-block tip"><p>When you only need the URL string and don&#39;t need options like <code>nesting</code> or <code>sites</code>, the <code>|link</code> filter provides a simpler syntax for passing URL parameters. See <a href="#supplying-url-parameters">Supplying URL Parameters</a> above.</p></div><h2 id="php-interface"><a href="#php-interface" class="header-anchor">#</a> PHP Interface</h2><p>You may resolve links in PHP using the <code>Cms\\Classes\\PageManager</code> class. The <code>url</code> method returns a string to the public URL.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name class-name-fully-qualified static-context">Cms<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>PageManager</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;october://cms-page@link/about&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You may pass URL parameters as the second argument to supply values for the target page&#39;s URL pattern.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name class-name-fully-qualified static-context">Cms<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>PageManager</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">custom_page</span><span class="token punctuation">,</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;slug&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">slug</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;id&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">id</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The <code>resolve</code> method returns a detailed <code>Cms\\Models\\PageLookupItem</code> object.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$page</span> <span class="token operator">=</span> <span class="token class-name class-name-fully-qualified static-context">Cms<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>PageManager</span><span class="token operator">::</span><span class="token function">resolve</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;october://cms-page@link/about&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">echo</span> <span class="token variable">$page</span><span class="token operator">-&gt;</span><span class="token property">url</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../../element/form/widget-pagefinder.html">Page Finder Form Widget</a></li></ul></div>`,35))])}const v=p(u,[["render",r]]);export{f as __pageData,v as default};
